{
 "quarter": "Q1 FY27",
 "callDate": "2026-07-16",
 "guidance": [
  {
   "metric": "margin",
   "statement": "Maintain medium- to long-term Wires & Cables EBIT margin guidance of 11% to 13%.",
   "quote": "Consistent with our Project Spring roadmap, we continue to maintain our medium- to long-term margin guidance of 11% to 13% for this business.",
   "page": 5,
   "horizon": "medium to long term",
   "quantitative": true
  },
  {
   "metric": "margin",
   "statement": "Target FMEG EBITDA margins of 8% to 10% by FY 2030.",
   "quote": "EBIT margins for the quarter were 8%, very much in line with the milestones laid out under Project Spring, where we target EBITDA margins of 8% to 10% by FY 2030.",
   "page": 6,
   "horizon": "FY27 to FY30",
   "quantitative": true
  },
  {
   "metric": "revenue",
   "statement": "Target FMEG revenue growth at 1.5x to 2x of industry growth.",
   "quote": "Our strategic priorities remain unchanged to grow at 1.5x to 2x of the industry growth while progressively enhancing profitability.",
   "page": 6,
   "horizon": "medium term",
   "quantitative": true
  },
  {
   "metric": "revenue",
   "statement": "Expect overall growth at 1.5x of market growth, combining volume and value.",
   "quote": "I think we have always guided that we will do 1.5x of market growth, which is a mix of both volume and value.",
   "page": 9,
   "horizon": "full year / medium term",
   "quantitative": true
  },
  {
   "metric": "margin",
   "statement": "Expect sustainable operating margins for the EPC business to remain in the high single-digit range.",
   "quote": "Over the medium to long term, we continue to expect sustainable operating margins for the EPC business to remain in the high single-digit range.",
   "page": 6,
   "horizon": "medium to long term",
   "quantitative": false
  },
  {
   "metric": "revenue",
   "statement": "Export growth target of going north of 10% of overall top line by 2030.",
   "quote": "We have given our guidance of going north of 10% of our overall top line by 2030.",
   "page": 18,
   "horizon": "by 2030",
   "quantitative": true
  }
 ],
 "delivered": [
  {
   "metric": "revenue",
   "statement": "Consolidated revenues grew by 39% year-on-year.",
   "page": 4
  },
  {
   "metric": "margin",
   "statement": "EBITDA increased by 32% YoY with margins at 13.8%, improving 70 bps sequentially.",
   "page": 4
  },
  {
   "metric": "profit",
   "statement": "Achieved highest ever quarterly Profit After Tax of INR 7,967 million, up 33% YoY.",
   "page": 4
  },
  {
   "metric": "revenue",
   "statement": "Wires & Cables segment registered a healthy 39% YoY growth.",
   "page": 5
  },
  {
   "metric": "revenue",
   "statement": "FMEG segment delivered 71% YoY growth, marking the tenth consecutive quarter outperforming industry growth.",
   "page": 5
  },
  {
   "metric": "revenue",
   "statement": "EPC business reported revenues of INR 3,077 million, down 11% YoY.",
   "page": 6
  }
 ],
 "tone": "confident on domestic demand and strategic momentum, cautious on global geopolitical uncertainties and near-term volatility.",
 "pushback": [
  {
   "topic": "Working capital & LCs",
   "gist": "Analysts questioned the increase in acceptances and payable days, and the accounting treatment of interest costs.",
   "page": 5
  },
  {
   "topic": "Export slowdown",
   "gist": "Scepticism regarding the 13% decline in exports and the heavy reliance on the Middle East.",
   "page": 6
  },
  {
   "topic": "Channel stocking",
   "gist": "Pressed on whether falling raw material prices led to suboptimal channel stocking and weak volume growth.",
   "page": 11
  },
  {
   "topic": "Volume growth sustainability",
   "gist": "Concerned about lower volume growth over recent quarters and whether T&D/data centre demand could face delays.",
   "page": 16
  }
 ]
}
